package com.agacostays.billing.consumer;import com.agacostays.billing.service.BillingService;import com.fasterxml.jackson.databind.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import java.math.BigDecimal;
@Component public class CheckoutCompletedEventConsumer{private final BillingService s;private final ObjectMapper m;public CheckoutCompletedEventConsumer(BillingService s,ObjectMapper m){this.s=s;this.m=m;}@KafkaListener(topics="checkout.completed",groupId="billing-service-checkout")public void consume(String msg){try{JsonNode n=m.readTree(msg);Long b=v(n,"bookingId"),br=v(n,"branchId"),c=v(n,"customerId");if(b!=null&&br!=null&&c!=null)s.getOrCreateFromCheckoutEvent(b,br,c,d(n,"roomCharges"),d(n,"restaurantCharges"));}catch(Exception ignored){}}private Long v(JsonNode n,String f){return n.hasNonNull(f)?n.get(f).asLong():null;}private BigDecimal d(JsonNode n,String f){return n.hasNonNull(f)?new BigDecimal(n.get(f).asText()):BigDecimal.ZERO;}}
